def read_receipt(receipt_file: Path, artifact_digest: str) -> dict:
    try:
        receipt = json.loads(receipt_file.read_text(encoding="utf-8"))
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        raise RccRuntimeError("receipt", "missing or malformed RCC receipt") from exc
    if not isinstance(receipt, dict) or receipt.get("artifactDigest") != artifact_digest:
        raise RccRuntimeError("receipt", "receipt artifact identity mismatch")
    verification = receipt.get("verification")
    if not isinstance(verification, dict) or verification.get("valid") is not True:
        raise RccRuntimeError("receipt", "receipt verification is not valid")
    if not isinstance(receipt.get("leaseId"), str) or not receipt["leaseId"]:
        raise RccRuntimeError("receipt", "receipt lease identity is missing")
    return receipt

def kill_process_and_subprocesses(pid, soft_kill_timeout: float = 1.0):
    log.debug("Killing process and subprocesses of: %s", pid)
    import psutil

    try:
        proc = psutil.Process(int(pid))
        proc_children = proc.children(recursive=True)
        all_processes = [proc] + proc_children

        # Terminate (soft-kill) all processes
        for p in all_processes:
            try:
                p.terminate()
            except psutil.NoSuchProcess:
                continue
            except Exception as e:
                log.debug(f"Error terminating child process {p.pid}: {e}")

        # Wait a bit for all processes to terminate
        _gone, alive = psutil.wait_procs(all_processes, timeout=soft_kill_timeout)

        # Force kill any remaining children after the timeout elapses
        for p in alive:
            try:
                p.kill()
            except psutil.NoSuchProcess:
                continue
            except Exception as e:
                log.debug(f"Error killing child process {p.pid}: {e}")

    except psutil.NoSuchProcess:
        log.debug(f"Process {pid} not found")
    except Exception as e:
        log.debug(f"Error killing process and subprocesses of {pid}: {e}")

